
(() => {
  const SDD_BG = "data:image/webp;base64,";
  const ENTERPRISE_DASHBOARD = "data:image/webp;base64,";

  const q=(s,r=document)=>r.querySelector(s); const qa=(s,r=document)=>Array.from(r.querySelectorAll(s));
  function ready(fn){ if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',fn,{once:true}); else fn(); }
  function slideNo(el,i){ const s=((el.dataset.slideOrder||'')+' '+(el.dataset.slide||'')+' '+(q('img',el)?.alt||'')).toLowerCase(); const m=s.match(/(?:slide|s|__s|\b)(\d{1,2})\b/); return m?Number(m[1]):i+1; }
  function naturalRatio(stage){ const img=q('img',stage); if(!img) return; const set=()=>{ if(img.naturalWidth && img.naturalHeight) stage.style.setProperty('--final-ratio', `${img.naturalWidth} / ${img.naturalHeight}`);}; img.complete?set():img.addEventListener('load',set,{once:true}); }
  function initCarousel(card, config={}){
    if(!card || card.dataset.finalCarouselReady) return; card.dataset.finalCarouselReady='true';
    const stage=q('.archive-carousel-stage',card); const viewport=q('[data-archive-carousel]',card); const rail=q('.archive-carousel-rail',viewport);
    if(!stage||!viewport||!rail) return;
    let slides=qa('.archive-carousel-slide',rail).sort((a,b)=>slideNo(a,0)-slideNo(b,0));
    slides.forEach(s=>rail.appendChild(s));
    rail.style.width=(slides.length*100)+'%'; slides.forEach(s=>{s.style.flex='0 0 100%';s.style.width='100%'});
    stage.dataset.finalCarousel=''; naturalRatio(stage);
    let index=0;
    const render=()=>{rail.style.transform=`translate3d(-${index*(100/slides.length)}%,0,0)`;};
    const make=(dir,label,icon)=>{let b=document.createElement('button');b.type='button';b.className='final-carousel-button '+dir;b.dataset.finalCarouselButton=dir;b.setAttribute('aria-label',label);b.innerHTML=`<span class="material-symbols-rounded" aria-hidden="true">${icon}</span>`;b.__finalSlideHandler=()=>{index=(index+(dir==='next'?1:-1)+slides.length)%slides.length;render();};stage.appendChild(b);return b;};
    make('prev','Previous slide','arrow_back'); make('next','Next slide','arrow_forward');
    let startX=0,startY=0,pointer=false;
    viewport.addEventListener('pointerdown',e=>{pointer=true;startX=e.clientX;startY=e.clientY;viewport.setPointerCapture?.(e.pointerId);});
    viewport.addEventListener('pointerup',e=>{if(!pointer)return;pointer=false;const dx=e.clientX-startX,dy=e.clientY-startY;if(Math.abs(dx)>42&&Math.abs(dx)>Math.abs(dy)){index=(index+(dx<0?1:-1)+slides.length)%slides.length;render();}});
    viewport.addEventListener('pointercancel',()=>pointer=false); render();
  }
  function setImageAsset(selector, src, alt){const img=q(selector); if(img){img.src=src;img.alt=alt;img.loading='eager';}}
  function initNonLoopVideoControls(){
    qa('video').forEach(video=>{
      const source=q('source[data-video-src]',video); if(!source||video.loop||video.dataset.finalVideoReady) return;
      video.dataset.finalVideoReady='true'; video.preload='metadata'; video.muted=true; video.playsInline=true;
      const host=video.parentElement; if(!host) return; host.classList.add('final-video-host');
      qa('.portfolio-reel-control,.personal-reel-control,[data-portfolio-reel-control]',host).forEach(el=>el.remove());
      const btn=document.createElement('button');btn.type='button';btn.className='final-video-control';btn.textContent='Play';btn.setAttribute('aria-label','Play video');host.appendChild(btn);
      let loaded=false, blobUrl='';
      const ensureSource=()=>{if(loaded) return Promise.resolve();return new Promise((resolve,reject)=>{try{const uri=source.dataset.videoSrc;if(!uri) throw new Error('Video source unavailable');const comma=uri.indexOf(',');const raw=atob(uri.slice(comma+1));const size=1024*1024;let chunks=[];for(let i=0;i<raw.length;i+=size){let seg=raw.slice(i,i+size), bytes=new Uint8Array(seg.length);for(let j=0;j<seg.length;j++)bytes[j]=seg.charCodeAt(j);chunks.push(bytes);}blobUrl=URL.createObjectURL(new Blob(chunks,{type:'video/mp4'}));video.src=blobUrl;video.load();loaded=true;video.addEventListener('canplay',resolve,{once:true});video.addEventListener('error',()=>reject(new Error('Video cannot be loaded')),{once:true});}catch(err){reject(err);}})};
      const sync=()=>{const isPaused=video.paused;btn.textContent=isPaused?'Play':'Pause';btn.setAttribute('aria-label',isPaused?'Play video':'Pause video');};
      btn.addEventListener('click',async e=>{e.preventDefault();e.stopPropagation();try{if(!loaded){btn.textContent='Loading';await ensureSource();} if(video.paused) await video.play();else video.pause();sync();}catch(err){btn.textContent='Play';}});
      video.addEventListener('play',sync);video.addEventListener('pause',sync);video.addEventListener('ended',sync);
    });
  }
  function initFocusGrid(sel){qa(sel).forEach(grid=>{const items=Array.from(grid.children);items.forEach(item=>{item.addEventListener('mouseenter',()=>{grid.classList.add('is-focus-active');items.forEach(x=>x.classList.toggle('is-focus-target',x===item));});item.addEventListener('mouseleave',()=>{grid.classList.remove('is-focus-active');items.forEach(x=>x.classList.remove('is-focus-target'));});});});}
  
  function initSafari(){const unwanted='A visitor may know what they want to see, but still need quick answers: Where is it? What can I do there? When does an activity start? How do I get there?';qa('#safariView p').forEach(p=>{if(p.textContent.trim()===unwanted)p.remove();});const flow=q('#safariView .safari-process-flow');if(flow){const nodes=Array.from(flow.children);nodes.forEach((node,i)=>{node.tabIndex=0;const go=()=>flow.style.setProperty('--safari-progress',`${nodes.length<2?100:(i/(nodes.length-1))*100}%`);node.addEventListener('click',go);node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}});});}}
  function replaceEnterprise(){}
  function initHome(){const title=q('#homeView .hero-title, #homeView h1');if(title){title.innerHTML='YOGENDRA<br>CHAUDHARY <span aria-hidden="true">—</span><br>PRODUCT DESIGNER';}
    const copy=q('#heroCopy');if(copy){copy.setAttribute('aria-label',"A UI/UX and Product Designer focused on intuitive software interfaces, reusable components, and user-centered workflows\u2014turning complex product requirements into clear, usable experiences that people can navigate with confidence.");copy.innerHTML="<span class=\"hero-copy-group\">A UI/UX and Product Designer</span><span class=\"hero-copy-group\">focused on intuitive software interfaces and reusable components</span><span class=\"hero-copy-group\">\u2014turning complex product requirements into clear workflows</span><span class=\"hero-copy-group\">and usable experiences people can navigate with confidence.</span>";}
    
    qa('a[href="#work"]').forEach(a=>a.addEventListener('click',()=>setTimeout(()=>{const all=q('#homeView [data-filter="all"]');all?.click();},0)));}
  function initSdd(){const map=['SDD Instagram Content System','SDD Employee Gathering'];map.forEach(t=>{const h=qa('#sddToolsView h3').find(n=>n.textContent.trim()===t);initCarousel(h?.closest('article'));});
    // Fit the static cards to their asset instead of forcing a generic crop.
    qa('#sddToolsView .sdd-single-asset').forEach(stage=>naturalRatio(stage));
  }
  function blockArchivePopup(){window.addEventListener('click',e=>{const b=e.target.closest?.('.final-carousel-button');if(b){e.preventDefault();e.stopImmediatePropagation();b.__finalSlideHandler?.();return;}const inside=e.target.closest?.('[data-final-carousel]');if(inside){e.preventDefault();e.stopImmediatePropagation();}},true);}
  function initPersonal(){qa('#gatheringView [data-archive-carousel]').forEach(el=>initCarousel(el.closest('.personal-content-card')));}
  function setupExplore(){qa('.explore-project-card,.other-project-card,[data-explore-project]').forEach(card=>{const route=card.getAttribute('data-route')||card.dataset.route; if(!route)return;const home=q(`#projectsGrid .project-card[data-route="${route}"] .project-media img, #projectsGrid .project-card[data-route="${route}"] .project-media video`); if(home&&home.tagName==='IMG'&&!q('img',card)){const img=home.cloneNode(true);img.removeAttribute('id');img.className='explore-project-thumb';card.prepend(img);}});}
  ready(()=>{
    blockArchivePopup(); initHome(); initSafari(); replaceEnterprise();  initSdd(); initNonLoopVideoControls(); initFocusGrid('#sddToolsView .archive-documentation-grid, #sddToolsView .archive-documentation-photo-grid'); setupExplore();
    setImageAsset('#sddWebView #sdd-background .sddweb-real-shot--background img', SDD_BG, 'Service-platform interface reference');
  });
})();
